function transfer(PDO $pdo, int $from, int $to, int $amount): void
{
    $pdo->beginTransaction();

    try {
        $debit = $pdo->prepare(
            "UPDATE accounts SET balance = balance - ? WHERE id = ?",
        );
        $debit->execute([$amount, $from]);

        $credit = $pdo->prepare(
            "UPDATE accounts SET balance = balance + ? WHERE id = ?",
        );
        $credit->execute([$amount, $to]);

        $pdo->commit();
    } catch (Throwable $e) {
        $pdo->rollBack();

        throw $e;
    }
}

