function linearSearch(array $values, int $target): int
{
    foreach ($values as $index => $value) {
        if ($value === $target) {
            return $index;
        }
    }

    return -1;
}

function binarySearch(array $values, int $target): int
{
    $low = 0;
    $high = count($values) - 1;

    while ($low <= $high) {
        $mid = intdiv($low + $high, 2);

        if ($values[$mid] === $target) {
            return $mid;
        }

        if ($values[$mid] < $target) {
            $low = $mid + 1;
        } else {
            $high = $mid - 1;
        }
    }

    return -1;
}

function bubbleSort(array $values): array
{
    $length = count($values);

    for ($i = 0; $i < $length - 1; $i++) {
        $swapped = false;

        for ($j = 0; $j < $length - 1 - $i; $j++) {
            if ($values[$j] > $values[$j + 1]) {
                [$values[$j], $values[$j + 1]] = [$values[$j + 1], $values[$j]];
                $swapped = true;
            }
        }

        if (!$swapped) {
            break;
        }
    }

    return $values;
}

function selectionSort(array $values): array
{
    $length = count($values);

    for ($i = 0; $i < $length - 1; $i++) {
        $minimum = $i;

        for ($j = $i + 1; $j < $length; $j++) {
            if ($values[$j] < $values[$minimum]) {
                $minimum = $j;
            }
        }

        if ($minimum !== $i) {
            [$values[$i], $values[$minimum]] = [$values[$minimum], $values[$i]];
        }
    }

    return $values;
}

function insertionSort(array $values): array
{
    $length = count($values);

    for ($i = 1; $i < $length; $i++) {
        $current = $values[$i];
        $j = $i - 1;

        while ($j >= 0 && $values[$j] > $current) {
            $values[$j + 1] = $values[$j];
            $j--;
        }

        $values[$j + 1] = $current;
    }

    return $values;
}

function merge(array $left, array $right): array
{
    $merged = [];
    $i = 0;
    $j = 0;

    while ($i < count($left) && $j < count($right)) {
        if ($left[$i] <= $right[$j]) {
            $merged[] = $left[$i];
            $i++;
        } else {
            $merged[] = $right[$j];
            $j++;
        }
    }

    while ($i < count($left)) {
        $merged[] = $left[$i];
        $i++;
    }

    while ($j < count($right)) {
        $merged[] = $right[$j];
        $j++;
    }

    return $merged;
}

function mergeSort(array $values): array
{
    if (count($values) <= 1) {
        return $values;
    }

    $middle = intdiv(count($values), 2);
    $left = array_slice($values, 0, $middle);
    $right = array_slice($values, $middle);

    return merge(mergeSort($left), mergeSort($right));
}

function quickSort(array $values): array
{
    if (count($values) <= 1) {
        return $values;
    }

    $pivot = $values[0];
    $left = [];
    $right = [];

    for ($i = 1; $i < count($values); $i++) {
        if ($values[$i] < $pivot) {
            $left[] = $values[$i];
        } else {
            $right[] = $values[$i];
        }
    }

    return [...quickSort($left), $pivot, ...quickSort($right)];
}

function heapify(array &$values, int $size, int $root): void
{
    $largest = $root;
    $left = 2 * $root + 1;
    $right = 2 * $root + 2;

    if ($left < $size && $values[$left] > $values[$largest]) {
        $largest = $left;
    }

    if ($right < $size && $values[$right] > $values[$largest]) {
        $largest = $right;
    }

    if ($largest !== $root) {
        [$values[$root], $values[$largest]] = [$values[$largest], $values[$root]];
        heapify($values, $size, $largest);
    }
}

function heapSort(array $values): array
{
    $size = count($values);

    for ($i = intdiv($size, 2) - 1; $i >= 0; $i--) {
        heapify($values, $size, $i);
    }

    for ($end = $size - 1; $end > 0; $end--) {
        [$values[0], $values[$end]] = [$values[$end], $values[0]];
        heapify($values, $end, 0);
    }

    return $values;
}

class Graph
{
    private array $adjacency = [];

    public function addEdge(string $from, string $to, int $weight = 1): void
    {
        $this->adjacency[$from][$to] = $weight;
        $this->adjacency[$to][$from] = $weight;
    }

    public function neighbors(string $node): array
    {
        return $this->adjacency[$node] ?? [];
    }
}

function bfs(Graph $graph, string $start): array
{
    $visited = [$start => true];
    $order = [];
    $queue = [$start];
    $head = 0;

    while ($head < count($queue)) {
        $node = $queue[$head];
        $head++;
        $order[] = $node;

        foreach (array_keys($graph->neighbors($node)) as $neighbor) {
            if (!isset($visited[$neighbor])) {
                $visited[$neighbor] = true;
                $queue[] = $neighbor;
            }
        }
    }

    return $order;
}

function dfs(Graph $graph, string $start): array
{
    $visited = [];
    $order = [];
    $stack = [$start];

    while ($stack !== []) {
        $node = array_pop($stack);

        if (isset($visited[$node])) {
            continue;
        }

        $visited[$node] = true;
        $order[] = $node;

        $neighbors = array_keys($graph->neighbors($node));

        for ($i = count($neighbors) - 1; $i >= 0; $i--) {
            $stack[] = $neighbors[$i];
        }
    }

    return $order;
}

function dijkstra(Graph $graph, string $start, string $end): ?array
{
    $distances = [$start => 0];
    $previous = [];
    $visited = [];

    while (true) {
        $current = null;
        $best = PHP_INT_MAX;

        foreach ($distances as $node => $distance) {
            if (!isset($visited[$node]) && $distance < $best) {
                $best = $distance;
                $current = $node;
            }
        }

        if ($current === null || $current === $end) {
            break;
        }

        $visited[$current] = true;

        foreach ($graph->neighbors($current) as $neighbor => $weight) {
            $candidate = $distances[$current] + $weight;

            if (!isset($distances[$neighbor]) || $candidate < $distances[$neighbor]) {
                $distances[$neighbor] = $candidate;
                $previous[$neighbor] = $current;
            }
        }
    }

    if (!isset($distances[$end])) {
        return null;
    }

    $path = [$end];
    $node = $end;

    while (isset($previous[$node])) {
        $node = $previous[$node];
        $path[] = $node;
    }

    return [
        "distance" => $distances[$end],
        "path" => array_reverse($path),
    ];
}
